import csv
import json

# Re-do Q1 with the correct preheat definition: from ambient up to 150°C
# The ramp rate should be checked for all points where temp is below 150°C
# (i.e., the entire preheat section from start to when reaching 150°C)

tc_data = {}
tc_info = {}
with open('/app/data/thermocouples.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        key = (row['run_id'], row['tc_id'])
        if key not in tc_data:
            tc_data[key] = []
            tc_info[key] = row['tc_location']
        tc_data[key].append((float(row['time_s']), float(row['temp_c'])))

for key in tc_data:
    tc_data[key].sort()

mes_data = {}
with open('/app/data/mes_log.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        mes_data[row['run_id']] = row

all_runs = sorted(mes_data.keys())

RAMP_LIMIT = 2.0
PREHEAT_MAX = 150.0

result = {
    "ramp_rate_limit_c_per_s": RAMP_LIMIT,
    "violating_runs": [],
    "max_ramp_by_run": {}
}

for run_id in all_runs:
    target_tc = None
    for tc_id in ['TC1','TC2','TC3','TC4','TC5','TC6']:
        key = (run_id, tc_id)
        if key in tc_info and tc_info[key] == 'smallest_mass':
            target_tc = tc_id
            break

    if target_tc is None:
        result["max_ramp_by_run"][run_id] = {"tc_id": None, "max_preheat_ramp_c_per_s": None}
        continue

    key = (run_id, target_tc)
    pts = tc_data[key]

    max_ramp = 0.0
    # Preheat = from ambient to 150°C. Check ramp for intervals where 
    # starting temp < 150°C (before reaching preheat target)
    for i in range(1, len(pts)):
        t0, temp0 = pts[i-1]
        t1, temp1 = pts[i]
        if temp0 < PREHEAT_MAX:
            dt = t1 - t0
            dT = temp1 - temp0
            if dt > 0 and dT > 0:  # only positive ramps matter
                ramp = dT / dt
                if ramp > max_ramp:
                    max_ramp = ramp

    result["max_ramp_by_run"][run_id] = {
        "tc_id": target_tc,
        "max_preheat_ramp_c_per_s": round(max_ramp, 2)
    }

    if max_ramp > RAMP_LIMIT:
        result["violating_runs"].append(run_id)

result["violating_runs"].sort()

with open('/app/output/q01.json', 'w') as f:
    json.dump(result, f, indent=2)

print("Q1 (recalculated with preheat from ambient to 150C):")
print(f"  Violating runs: {result['violating_runs']}")
for run_id in all_runs:
    entry = result['max_ramp_by_run'][run_id]
    print(f"  {run_id}: tc={entry['tc_id']}, ramp={entry['max_preheat_ramp_c_per_s']}")

PYEOF

