import csv

# Verify Q5 by showing yield for each board family's runs
defect_data = {}
with open('/app/data/test_defects.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        run_id = row['run_id']
        if run_id not in defect_data:
            defect_data[run_id] = {'yield': None, 'defects': 0}
        if row['inspection_stage'] == 'SUMMARY':
            defect_data[run_id]['yield'] = float(row['fp_yield_pct'])
        else:
            count = int(row['count']) if row['count'] else 0
            defect_data[run_id]['defects'] += count

mes_data = {}
with open('/app/data/mes_log.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        mes_data[row['run_id']] = row

families = {}
for run_id in sorted(mes_data.keys()):
    family = mes_data[run_id]['board_family']
    families.setdefault(family, []).append(run_id)

for family in sorted(families.keys()):
    print(f"\n{family}:")
    runs_info = []
    for run_id in sorted(families[family]):
        yld = defect_data.get(run_id, {}).get('yield', 0)
        defects = defect_data.get(run_id, {}).get('defects', 0)
        downtime = float(mes_data[run_id]['downtime_s'])
        throughput = float(mes_data[run_id]['boards_per_min'])
        runs_info.append((run_id, yld, defects, downtime, throughput))

    # Sort as in Q5
    runs_info.sort(key=lambda x: (-x[1], x[2], x[3], -x[4]))
    for r in runs_info:
        marker = " <-- BEST" if r == runs_info[0] else ""
        print(f"  {r[0]}: yield={r[1]:.2f}%, defects={r[2]}, downtime={r[3]:.0f}s, throughput={r[4]:.3f}{marker}")
